<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
final class CopywritingStyleCompiler {
 public static function validate(array $d,array $targets=[]):array {$errors=[];$props=CopywritingDocument::catalog()['style_properties'];$scan=function($v,$path)use(&$scan,&$errors,$props){if(!is_array($v))return;foreach($v as $k=>$item){$p=$path.'.'.$k;if(is_array($item)&&!array_key_exists('value',$item)){$scan($item,$p);continue;}if(!in_array($k,$props,true)&&!preg_match('/^--cw-[a-z0-9-]+$/D',(string)$k)){$errors[]=['code'=>'STYLE_PROPERTY','path'=>$p,'message'=>'不支持的样式属性'];continue;}if($item===null)continue;$text=is_array($item)?(string)($item['value']??'').($item['unit']??''):(string)$item;$bad=preg_match('/[{};<>\\\\]|@import|expression\s*\(|javascript\s*:|data\s*:|\/\*/i',$text);$depth=0;foreach(str_split($text)as $c){if($c==='(')$depth++;if($c===')'&&--$depth<0)$bad=1;}if($depth!==0)$bad=1;if(is_array($item)&&(!is_numeric($item['value']??null)||!in_array($item['unit']??'',['px','rpx','%','rem','em','vw','vh','fr'],true)))$bad=1;if($bad)$errors[]=['code'=>'STYLE_VALUE','path'=>$p,'message'=>'样式值或单位不合法'];}};$walk=function($nodes)use(&$walk,$scan){foreach($nodes as $n){$scan($n['styles']??[],$n['id']??'');$walk($n['children']??[]);}};$walk($d['page']['nodes']??[]);return $errors;}
}
